INSERT INTO roles_utilisateur (role, description) VALUES
('directeur', 'Le directeur est responsable de la gestion globale de l''entreprise. Il prend des décisions stratégiques, supervise les opérations et assure la coordination entre les différents départements.'),
('manager_gestion_stock', 'Le manager de gestion de stock est responsable de la supervision des activités liées à la gestion des stocks. Il s''assure que les niveaux de stock sont maintenus, gère les commandes et coordonne avec les fournisseurs pour garantir un approvisionnement efficace.'),
('employe_gestion_stock', 'L''employé de gestion de stock est chargé de la réception, du stockage et de la distribution des produits. Il effectue des inventaires réguliers, met à jour les registres de stock et collabore avec le manager pour assurer une gestion efficace des stocks.'),
('manager_vente', 'Le manager de vente est responsable de la supervision des activités de vente. Il établit des objectifs de vente, forme et motive l''équipe de vente, et analyse les performances pour atteindre les objectifs commerciaux.'),
('employe_vente', 'L''employé de vente est chargé d''interagir avec les clients, de promouvoir les produits et de conclure des ventes. Il fournit un excellent service client et travaille en étroite collaboration avec le manager de vente pour atteindre les objectifs de vente.');
('manager_finances', 'Le manager de finances est responsable de la gestion financière de l''entreprise. Il supervise les budgets, analyse les performances financières, et prend des décisions pour assurer la santé financière de l''entreprise.'),
('employe_finances', 'L''employé de finances est chargé de la tenue des registres financiers, de la préparation des rapports financiers et de l''assistance dans la gestion des budgets. Il travaille en étroite collaboration avec le manager de finances pour assurer une gestion financière efficace.');